def tr(key, lang='en', **kwargs):
    return COPY[key][LANGS.index(lang) if lang in LANGS else 0].format(**kwargs)


def install(locales):
    for index, lang in enumerate(LANGS):
        locales[lang]['btn_workout'] = COPY['title'][index]
        locales[lang]['btn_workout_goals'] = COPY['goals'][index]
        for key in ('btn_add_workout', 'btn_workout_done', 'btn_workout_cancel', 'btn_workout_template',
                    'btn_workout_today', 'btn_workout_history', 'btn_workout_templates', 'btn_workout_frequency',
                    'btn_workout_frequency_default',
                    'workout_input_prompt', 'workout_input_added', 'workout_input_invalid', 'workout_cancelled',
                    'workout_empty', 'workout_parsing', 'workout_parse_error', 'workout_draft_limit', 'unknown_intensity'):
            locales[lang][key] = COPY[key][index]

